create table public.supplier_reviews(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.suppliers(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,period_start date not null,period_end date not null,frequency text not null check(frequency in('MONTHLY','QUARTERLY','SEMIANNUAL','ANNUAL')),sla_score numeric(5,2) check(sla_score between 0 and 100),quality_score numeric(5,2) check(quality_score between 0 and 100),service_score numeric(5,2) check(service_score between 0 and 100),communication_score numeric(5,2) check(communication_score between 0 and 100),security_score numeric(5,2) check(security_score between 0 and 100),overall_score numeric(5,2) not null check(overall_score between 0 and 100),comments text,created_at timestamptz not null default now(),created_by uuid references public.user_profiles(id) on delete set null,check(period_end>=period_start),unique(supplier_id,period_start,period_end));
create index supplier_reviews_org_period_idx on public.supplier_reviews(organization_id,period_end desc);
alter table public.supplier_reviews enable row level security;
create policy "members read supplier reviews" on public.supplier_reviews for select to authenticated using(public.is_organization_member(organization_id));
create policy "managers manage supplier reviews" on public.supplier_reviews for all to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[])) with check(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]));
